DO $$ DECLARE fn record; def text; BEGIN FOR fn IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('change_appointment','create_my_doctor_profile','update_my_doctor_profile','set_doctor_presence','admin_set_account_status','admin_users','review_appointment_refund','review_doctor_application') LOOP def:=pg_get_functiondef(fn.oid); def:=regexp_replace(def,'\mBEGIN\M',E'BEGIN\n IF auth.uid() IS NOT NULL AND NOT public.registration_contacts_verified(auth.uid()) THEN RAISE EXCEPTION ''Email and phone verification required''; END IF;', 'i'); EXECUTE def; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.my_doctor_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.doctors WHERE user_id=auth.uid() AND public.registration_contacts_verified(auth.uid()) $$;
CREATE FUNCTION public.my_registration_status() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('required',v.required,'email_confirmed',u.email_confirmed_at IS NOT NULL,'phone_verified',v.phone_verified_at IS NOT NULL AND v.verified_phone=p.phone,'phone',p.phone) FROM public.registration_verifications v JOIN public.profiles p ON p.id=v.user_id JOIN auth.users u ON u.id=v.user_id WHERE v.user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.my_registration_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_registration_status() TO authenticated;